contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val) public payable {
        require(true);
        bool setMinSumReverted;
        bool initializedReverted;

        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setMinSumReverted = true; } else { setMinSumReverted = false; }
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initializedReverted = true; } else { initializedReverted = false; }

        assert(!setMinSumReverted && !initializedReverted);
    }
}

