// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        vm.assume(true);
        bool setMinSumReverted;
        bool initializedReverted;
        try c.SetMinSum(val) { setMinSumReverted = false; } catch { setMinSumReverted = true; }
        try c.Initialized() { initializedReverted = false; } catch { initializedReverted = true; }
        assertTrue(!setMinSumReverted && !initializedReverted);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
